import{_ as t,o as i,c as a,ag as s}from"./chunks/framework.BFM5MFIQ.js";const r="data:image/svg+xml;base64,",p=JSON.parse('{"title":"Persistent storage","description":"What persistent storage means and what to do when the browser refuses it.","frontmatter":{"title":"Persistent storage","description":"What persistent storage means and what to do when the browser refuses it.","order":10},"headers":[],"relativePath":"en/troubleshooting/persistent-storage.md","filePath":"en/troubleshooting/persistent-storage.md"}'),n={name:"en/troubleshooting/persistent-storage.md"};function o(l,e,I,d,g,h){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="persistent-storage" tabindex="-1">Persistent storage <a class="header-anchor" href="#persistent-storage" aria-label="Permalink to &quot;Persistent storage&quot;">​</a></h1><p>Owlbear&#39;s DMH stores campaign data locally in the browser. Persistent storage is a browser hint that the data should not be cleared automatically when the device is low on space.</p><p>The browser decides whether to grant it. It may refuse for a site that is not installed, has little history, or is in a private window.</p><p><img src="'+r+'" alt="Site settings in a browser"></p><h2 id="chrome-and-edge" tabindex="-1">Chrome and Edge <a class="header-anchor" href="#chrome-and-edge" aria-label="Permalink to &quot;Chrome and Edge&quot;">​</a></h2><ol><li><a href="./../getting-started/install.html">Install the app</a> first. Installed apps are more likely to be granted persistent storage.</li><li>Open the site information panel from the icon to the left of the address bar and review <strong>Site settings</strong>.</li><li>Make sure cookies and site data are allowed for this site.</li><li>Return to <strong>Settings → Content → Persistent storage</strong> and request it again.</li></ol><p>Chrome and Edge do not expose a separate “persistent storage” switch. The browser grants it automatically based on installation and engagement, so installing the app and using it normally is the reliable path.</p><h2 id="firefox" tabindex="-1">Firefox <a class="header-anchor" href="#firefox" aria-label="Permalink to &quot;Firefox&quot;">​</a></h2><p>Firefox may prompt when a site requests persistent storage. If permission was blocked, open the site information panel, review the site permissions, and try again. You can also check the browser&#39;s stored site data settings.</p><h2 id="safari" tabindex="-1">Safari <a class="header-anchor" href="#safari" aria-label="Permalink to &quot;Safari&quot;">​</a></h2><p>Safari manages website storage per site. Review the website&#39;s storage settings from the address bar or from Safari settings. On iOS, check <strong>Settings → Safari → Advanced → Website Data</strong>.</p><h2 id="if-it-is-still-denied" tabindex="-1">If it is still denied <a class="header-anchor" href="#if-it-is-still-denied" aria-label="Permalink to &quot;If it is still denied&quot;">​</a></h2><ul><li>Install the app and open it from the installed entry.</li><li>Use the app normally for a while, then request persistence again.</li><li>Keep a recent backup before clearing browser data or changing site settings.</li></ul><p><a href="./../getting-started/install.html">Back to installing the app</a></p>',14)])])}const c=t(n,[["render",o]]);export{p as __pageData,c as default};
